  if ((route === "signin" || route === "signin/renew") && body && typeof body.idToken === "string") {
    const c = tokenClaims(body.idToken), person = personHash(w, c.iss, c.sub);
    for (const v of [c.tid, c.hd, c.iss]) if (typeof v === "string" && v !== CONSUMERS)
      for (const id of ids) put.run(person, id, person, String(body.provider), orgKey(w, String(body.provider), v));
  }
  w.db.raw.prepare("INSERT OR IGNORE INTO lead_names (licence, person, named_by, at" + (acc ? ", accepted_at" : "") + ") SELECT a.licence, s.person, 'legacy', 0" + (acc ? ", 0" : "") + " FROM seats s "
    + "JOIN admits a ON a.provider = s.provider AND a.org = s.org JOIN licences l ON l.id = a.licence WHERE s.kind = 'lead' "
    + "AND substr(a.org, 1, 7) <> 'person:' AND l.owner IS NOT s.person AND a.licence IN (" + ids.map(Number).join(", ") + ")").run();
