  const seat = proofKept(w) ? w.db.raw.prepare("SELECT licence FROM seats WHERE kind = 'lead' AND code = ?").get(q.owner) : null;
  if (standing) w.db.raw.prepare("UPDATE seats SET seen_at = 0, proved_at = 0 WHERE kind = 'lead' AND code = ?").run(standing);
  const id = seat ? seat.licence : (w.db.raw.prepare("SELECT id FROM licences WHERE key_hash = ?").get(r.tag) || {}).id;
