/** Every row of every table, as text, to look for a value kept in the clear. */
function dumpOf(w) {
  return w.db.raw.prepare("SELECT name FROM sqlite_master WHERE type = 'table'").all()
    .map(t => JSON.stringify(w.db.raw.prepare("SELECT * FROM \"" + t.name + "\"").all())).join(NL);
}
/** A database's shape: each table's columns (name, type, not null, default, key) and each index's name and table. */
function shapeOf(sql) {
  const { DatabaseSync } = nodeRequire("node:sqlite");
  const db = new DatabaseSync(":memory:");
  db.exec(sql);
  const out = db.prepare("SELECT type, name, tbl_name FROM sqlite_master WHERE name NOT LIKE 'sqlite_%' ORDER BY type, name").all()
    .map(r => r.type + " " + r.name + " " + r.tbl_name + (r.type === "table"
      ? " " + JSON.stringify(db.prepare("PRAGMA table_info(\"" + r.name + "\")").all().map(c => [c.name, c.type, c.notnull, c.dflt_value, c.pk]).sort())
      : " " + JSON.stringify(db.prepare("PRAGMA index_info(\"" + r.name + "\")").all().map(c => c.name))
        + " " + JSON.stringify(db.prepare("PRAGMA index_list(\"" + r.tbl_name + "\")").all().filter(i => i.name === r.name).map(i => [i.unique, i.partial]))));
  db.close();
  return out.join(NL);
}

