/* ---- the desk's answers, recorded (s110; the engine's desk-signin ds23 reads the same file) ------------------------------- */
const ANSWERS = path.join(HERE, "fixtures", "signin-answers.json");
const ANSWERS_KIND = "etiuda-signin-answers";
/* An answer's shape, to compare two recordings whose keys, codes and times differ: each object's names sorted, a fixed word kept,
   and a value that varies by run named by its class (an integer, an address, hex or a code of its length, a key's id). */
function answerShape(v) {
  if (v === null || typeof v === "boolean") return v;
  if (typeof v === "number") return Number.isInteger(v) ? "<int>" : "<num>";
  if (typeof v === "string") {
    if (/^https?:\/\//.test(v)) return "<url>";
    if (v.length >= 8 && /^[0-9a-f]+$/.test(v)) return "<hex" + v.length + ">";
    if (v.length >= 8 && /^[0-9A-Z]+$/.test(v)) return "<A" + v.length + ">";
    return v.replace(/[0-9a-f]{8,}/g, m => "<hex" + m.length + ">");
  }
  if (Array.isArray(v)) return Array.from(new Set(v.map(x => JSON.stringify(answerShape(x))))).sort();
  return Object.fromEntries(Object.keys(v).sort().map(k => [k, (k === "id" || k === "keyId") && typeof v[k] === "string" ? "<id>" : answerShape(v[k])]));
}
