      "licence/set": () => setSwitch(w, k, true, { t: tt() }), "seat/free": () => freeSeat(w, k, "lead", s1.body.me, { t: tt() }),
      "seat/stay": () => staySeat(w, k, "desk", [], { t: tt() }),
      /* The one act's lead acts, each answered ok to a lead whatever it found: a pass to the lead lead/name named just before, a refusal, an
         invitation and its withdrawal. */
      "ask/pass": () => passAsk(w, k, "5c".repeat(16), personOn(w, lic86.id, personHash(w, msIss(TENANT_A), "s86-p1"))),
      "ask/refuse": () => refuseAsk(w, k, "5c".repeat(16)), "invite": () => inviteAddr(w, k, "s86@contoso.example"),
      "invite/withdraw": () => withdrawInvite(w, k, "s86@contoso.example"),
      "lead/invite": () => nameAddr(w, k, "s86.named@contoso.example"),
      "lead/pick": () => namePerson(w, k, personOn(w, lic86.id, personHash(w, msIss(TENANT_A), "s86-p1"))),
      "lead/withdraw": () => withdrawNaming(w, k, "5c".repeat(16)),
