      const leaderPers = personHash(wj, msIss(TENANT_A), "s102j-leader");
      const leaderDesk = await deskSignin(wj, msToken(wj, { sub: "s102j-leader", tid: TENANT_A }), { desk: "s102j-l-d" });
      const leaderTrial = wj.db.raw.prepare("SELECT * FROM licences WHERE owner = ? AND desk_only = 1").get(leaderPers);
      const teamLead = newKey();
