    const hasPurge = typeof K.core.purgeRetention === "function";
    /* Exactly 12 months after deadPaid ended (and 10 days before refLic reaches 12 months): neither is purged yet. */
    w.clock.now = deadPaidUntil + (retMs || 365 * DAY);
    if (hasPurge) await K.core.purgeRetention(w.db, w.clock.now);
