    const takes = (cert, pub) => !!cert && certHolds(cert) && cert.licence === ref && cert.desk === pub && window(cert) && cert.member === undefined
      && RELAY.certWhy(cert, pub, [ref], w.clock.now, [ROOTK.pub]) === null;
