    const id = w.bound(k), row = id ? w.db.raw.prepare("SELECT trial_ends FROM licences WHERE id = ?").get(id) : null;
    const ends = row ? row.trial_ends : 0, person = personHash(w, msIss(TENANT_A), "rs7e-lead"), at = w.clock.now, c = s.body && s.body.certificates;
    const signedAt = memberAndStudio(c, k) && memberHolds(w, c.member, m.pub, id, person, s.body.me, at, Math.min(at + MEMBER_MS, ends));
    w.clock.now += DAY;
    const r = await renew(w, k, MS, msToken(w, { sub: "rs7e-lead" }), { member: m.pub, t: w.clock.now + 2 });
    const c2 = r.body && r.body.certificates;
    const renewed = memberAndStudio(c2, k) && memberHolds(w, c2.member, m.pub, id, person, r.body.me, w.clock.now, Math.min(w.clock.now + MEMBER_MS, ends));
