    const moved = await deskSignin(w, idt(w, O.sub), { access: acc(w, O.sub, undefined), renew: true, desk: "q13d-d", t: O.tn() });
    const card = await adminCard(w, newKey(), idt(w, "q13d-admin"), { access: acc(w, "q13d-admin", ["Etiuda.Admin"]), t: O.tn() });
