    /* (b) Admitted by code (orgDesks off, the default), 1 desk seat on the team licence, 1 on P's desk-only licence. */
    const { w: wb, ko: kob, lic: lb, tn: tnb } = await teamOf("q14b", { seats: 1 });
    const bb0 = await deskSignin(wb, msToken(wb, { sub: "q14b-b" }), { desk: "q14b-bd", t: tnb() });
    await admitPerson(wb, kob, bb0.body.code, { t: tnb() });
