    hadDeskTrial(wb, personHash(wb, msIss(TENANT_A), "q14b-p"));
    const pb0 = await deskSignin(wb, msToken(wb, { sub: "q14b-p" }), { desk: "q14b-pd1", t: tnb() });
    await admitPerson(wb, kob, pb0.body.code, { t: tnb() });
