    /* This Worker over the migrated rows. */
    w.clock.now = t0 + DAY;
    const aStudio = await signin(w, newKey(), GOOG, googleToken(w, { sub: "tw4-a" }));
    const bDesk = await deskSignin(w, googleToken(w, { sub: "tw4-b" }), { desk: "tw4-b" });
    const aDesk = await deskSignin(w, googleToken(w, { sub: "tw4-a" }), { desk: "tw4-a" });
    const aRow = after.find(x => x.key_hash === "signin:tw4-a");
    const bRows = w.db.raw.prepare("SELECT COUNT(*) AS n FROM licences WHERE owner = ?").get(P("tw4-b")).n;
    /* The undo now: B and F go back, A stays under "desk:" (its person's Studio trial holds "person:"); without the guard, refused. */
    const db4 = standInD1(K.schema);
    for (const r of rows(w.db)) db4.raw.prepare("INSERT INTO licences (" + Object.keys(r).join(", ") + ") VALUES (" + Object.keys(r).map(() => "?").join(", ") + ")").run(...Object.values(r));
    let unguarded = "taken";
