      const t0a = tablesOf(S1.w), ch0a = S1.w.db.raw.prepare("SELECT total_changes() AS n").get().n;
      const ra = await deskSignin(S1.w, S1.tok(), { renew: true, desk: S1.desk, t: S1.tn() });
      const t1a = tablesOf(S1.w), ch1a = S1.w.db.raw.prepare("SELECT total_changes() AS n").get().n;

      const S2 = await setup("s152k2", "S152k-m");
      const t0b = tablesOf(S2.w), ch0b = S2.w.db.raw.prepare("SELECT total_changes() AS n").get().n;
      const rb = await deskSignin(S2.w, S2.tok(), { renew: true, desk: S2.desk, t: S2.tn() });
      const t1b = tablesOf(S2.w), ch1b = S2.w.db.raw.prepare("SELECT total_changes() AS n").get().n;

      const dA = ch1a - ch0a, dB = ch1b - ch0b;
