  V.entries = (await vectorEntries(V, RQ)).map(e => Object.assign(e, { sig: signerOf(V, keys, e).sign(Buffer.from(e.text, "utf8")) }));
  fs.writeFileSync(VECTOR, JSON.stringify(V, null, 1) + NL);
