const FILES = ["core.mjs", "requests.mjs", "schema.sql", "pay.mjs", "pay-paddle.mjs", "pay-stripe.mjs", "attach.mjs", "erase.mjs"];

async function plantedModules(p) {
  const dir = path.join(SCRATCH, "plant-" + p.name);
  fs.mkdirSync(dir, { recursive: true });
  const texts = Object.fromEntries(FILES.map(f => [f, fs.readFileSync(path.join(SERVICE, f), "utf8")]));
  for (const [file, from, to] of p.subs) {
    if (file === "scripts/attach-seats.mjs" || file === "scripts/erase-person.mjs" || file === "scripts/lead-seats.mjs" || file === "migrations/0016_erase.sql" || file === "migrations/0020_erasure2.sql") continue;
    const n = texts[file].split(from).length - 1;
    if (n !== 1) throw new Error("plant " + p.name + ": the line it changes is in " + file + " " + n + " times, not once: " + from.slice(0, 60));
    texts[file] = texts[file].split(from).join(to);
  }
  for (const f of FILES) fs.writeFileSync(path.join(dir, f), texts[f]);
  const url = f => pathToFileURL(path.join(dir, f)).href;
  /* attach-seats.mjs and erase-person.mjs beside the copies, their own subs applied, reading the copies and the real target.mjs and src/. */
  let at = fs.readFileSync(path.join(SERVICE, "scripts", "attach-seats.mjs"), "utf8");
  for (const [file, from, to] of p.subs) if (file === "scripts/attach-seats.mjs") {
    if (at.split(from).length !== 2) throw new Error("plant " + p.name + ": the line it changes is not in attach-seats.mjs once");
    at = at.split(from).join(to);
  }
  at = at.split('from "../').join('from "./').split('from "./target.mjs"').join('from ' + JSON.stringify(pathToFileURL(path.join(SERVICE, "scripts", "target.mjs")).href))
    .split('import("../../../').join('import(' + JSON.stringify(pathToFileURL(ROOT).href + "/").slice(0, -1));
  fs.writeFileSync(path.join(dir, "attach-seats.mjs"), at);
  let es = fs.readFileSync(path.join(SERVICE, "scripts", "erase-person.mjs"), "utf8");
  for (const [file, from, to] of p.subs) if (file === "scripts/erase-person.mjs") {
    if (es.split(from).length !== 2) throw new Error("plant " + p.name + ": the line it changes is not in erase-person.mjs once");
    es = es.split(from).join(to);
  }
  es = es.split('from "../').join('from "./').split('from "./target.mjs"').join('from ' + JSON.stringify(pathToFileURL(path.join(SERVICE, "scripts", "target.mjs")).href));
  fs.writeFileSync(path.join(dir, "erase-person.mjs"), es);
  /* lead-seats.mjs beside the copies, its own subs applied, reading the planted core and the real target.mjs. */
  let ls = fs.readFileSync(path.join(SERVICE, "scripts", "lead-seats.mjs"), "utf8");
  for (const [file, from, to] of p.subs) if (file === "scripts/lead-seats.mjs") {
    if (ls.split(from).length !== 2) throw new Error("plant " + p.name + ": the line it changes is not in lead-seats.mjs once");
    ls = ls.split(from).join(to);
  }
  ls = ls.split('from "../').join('from "./').split('from "./target.mjs"').join('from ' + JSON.stringify(pathToFileURL(path.join(SERVICE, "scripts", "target.mjs")).href));
  fs.writeFileSync(path.join(dir, "lead-seats.mjs"), ls);
  let m16 = fs.readFileSync(path.join(SERVICE, "migrations", "0016_erase.sql"), "utf8");
  for (const [file, from, to] of p.subs) if (file === "migrations/0016_erase.sql") {
    const norm = m16.replace(/\r\n/g, "\n");
    if (norm.split(from).length !== 2) throw new Error("plant " + p.name + ": the line it changes is not in 0016_erase.sql once");
    m16 = norm.split(from).join(to);
  }
  let m20 = fs.readFileSync(path.join(SERVICE, "migrations", "0020_erasure2.sql"), "utf8");
  for (const [file, from, to] of p.subs) if (file === "migrations/0020_erasure2.sql") {
    if (m20.split(from).length !== 2) throw new Error("plant " + p.name + ": the line it changes is not in 0020_erasure2.sql once");
    m20 = m20.split(from).join(to);
  }
  return { dupe: p.dupe, core: await import(url("core.mjs")), Q: await import(url("requests.mjs")), schema: texts["schema.sql"], AT: await import(url("attach-seats.mjs")), atText: at,
    E: await import(url("erase.mjs")), A: await import(url("attach.mjs")), ES: await import(url("erase-person.mjs")), LS: await import(url("lead-seats.mjs")), m16, m20 };
}

/* ---- main ----------------------------------------------------------------------------------------------------------- */

async function main(argv) {
  if (argv.includes("--write-vector")) { await writeVector(); return 0; }
  if (argv.includes("--write-answers")) { await writeAnswers(); return 0; }
  clearScratch(SCRATCH);
  const before = Object.fromEntries(FILES.map(f => [f, sha(fs.readFileSync(path.join(SERVICE, f)))]));
  const real = { core: C, Q: RQ, schema: SCHEMA, AT, E: ERS, A: ATS, ES: ESP,
    m16: fs.readFileSync(path.join(SERVICE, "migrations", "0016_erase.sql"), "utf8"),
    m20: fs.readFileSync(path.join(SERVICE, "migrations", "0020_erasure2.sql"), "utf8") };
  /* The network's tripwire (s52): while the legs run, globalThis.fetch counts and refuses; the service reaches the
     providers' keys only through the stand-in each world hands it. */
  const realFetch = globalThis.fetch;
  globalThis.fetch = async () => { NET.calls++; throw new Error("no leg reaches the network"); };
  try { await legs(real, check); } finally { globalThis.fetch = realFetch; }

  const only = process.env.LICENCE_SERVICE_PLANT;
  for (const p of PLANTS.filter(x => !only || x.name === only)) {
    if (PLANTS_OFF) { skip("s27 plant " + p.name + " turns " + p.reds.join(" and ") + " red (ETIUDA_PLANTS=off)"); continue; }
    const seen = [];
    try {
      const K = await plantedModules(p);
      /* With LICENCE_SERVICE_PLANT set, the planted run's own FAIL lines are printed, to be read. */
      await legs(K, (cond, line) => { if (!cond) { seen.push(String(line).split(" ")[0]); if (only) process.stdout.write("  FAIL (planted " + p.name + ") " + line + NL); } });
    } catch (e) { seen.push("broken: " + e.message); }
    check(p.reds.every(id => seen.includes(id)) && !seen.some(s => s.startsWith("broken")),
      "s27 plant " + p.name + " turns " + p.reds.join(" and ") + " red: " + JSON.stringify(seen));
  }
  const after = Object.fromEntries(FILES.map(f => [f, sha(fs.readFileSync(path.join(SERVICE, f)))]));
  if (PLANTS_OFF) skip("s27z the service's files are byte for byte as before the plants (ETIUDA_PLANTS=off)");
  else check(FILES.every(f => before[f] === after[f]), "s27z the service's files are byte for byte as before the plants");

  if (!argv.includes("--keep")) dropScratch(SCRATCH, "licence-service");
  process.stdout.write("#counts checks=" + asserted + " skipped=" + skipped + " failed=" + failed + " expected=" + EXPECTED + " plants=" + PLANTS.length + NL);
  if (!only && asserted + skipped !== EXPECTED) {
    process.stderr.write("SUITE DID NOT COMPLETE: " + (asserted + skipped) + " of " + EXPECTED + " checks ran" + NL);
    return 78;
  }
  process.stdout.write(NL + "licence-service  " + asserted + " assertion(s), " + skipped + " skipped, " + failed + " failure(s)" + NL);
  return Math.min(failed, 77);
}

main(process.argv.slice(2)).then(c => process.exit(c), e => {
  process.stderr.write(String(e && e.stack || e) + NL); process.exit(2);
});
